package br.com.eventflow.model; import jakarta.persistence.*; import java.util.UUID; @Entity @Table(name="ingressos") public class Ingresso { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(unique=true) public String codigoUnico=UUID.randomUUID().toString(); public String status="ATIVO"; @ManyToOne public Pedido pedido; @ManyToOne public Evento evento; }